            public HashSet<string> DirectRigidPaths { get; } =
                new(StringComparer.OrdinalIgnoreCase);
            public HashSet<GameplayMeshTraversalFailure> Failures { get; } = [];
            public bool IsComplete { get; set; } = true;
        }

